import {waveformFor} from './audio-waveform.js';
import {sourceOffset} from './model.js';
import {addEnvelopePoint,envelopeDbAt,normalizeEnvelope,snapEnvelopeDb,ENVELOPE_MIN_DB,ENVELOPE_MAX_DB} from './clip-envelope.js';

export function dbToY(db,height){const value=Math.max(ENVELOPE_MIN_DB,Math.min(ENVELOPE_MAX_DB,+db||0)),ratio=value>=0?.28*(ENVELOPE_MAX_DB-value)/ENVELOPE_MAX_DB:.28+.72*Math.pow(-value/-ENVELOPE_MIN_DB,.5);return 3+ratio*Math.max(1,height-6)}
export function yToDb(y,height){const ratio=Math.max(0,Math.min(1,(y-3)/Math.max(1,height-6)));return ratio<=.28?ENVELOPE_MAX_DB*(1-ratio/.28):ENVELOPE_MIN_DB*Math.pow((ratio-.28)/.72,2)}
// Snap in screen pixels: the asymmetric dB scale must feel equally magnetic on either side.
export function snapEnvelopeDrag(value,height,latched=false,fine=false){
 const distance=Math.abs(dbToY(value,height)-dbToY(0,height)),threshold=fine?(latched?4:2):(latched?8:5);
 if(distance<=threshold)return{valueDb:0,latched:true};
 return{valueDb:snapEnvelopeDb(value,fine),latched:false};
}
const xAt=(time,duration,width)=>3+Math.max(0,Math.min(1,time/Math.max(duration,1e-6)))*Math.max(1,width-6);
const timeAt=(x,duration,width)=>Math.max(0,Math.min(duration,(x-3)/Math.max(1,width-6)*duration));

export function drawClipEnvelope(canvas,points,duration,{active=false,selectedId=null,waveform=null,clip=null}={}){
 const rect=canvas.getBoundingClientRect(),ratio=Math.min(2,globalThis.devicePixelRatio||1),width=Math.max(1,Math.round(rect.width*ratio)),height=Math.max(1,Math.round(rect.height*ratio));if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height}const ctx=canvas.getContext('2d');ctx.setTransform(ratio,0,0,ratio,0,0);const w=rect.width,h=rect.height,p=normalizeEnvelope(points,duration);ctx.clearRect(0,0,w,h);
 if(waveform&&clip){ctx.strokeStyle=active?'#80aab6b0':'#80aab680';ctx.lineWidth=1;ctx.beginPath();const center=h*.59,amplitude=h*.34;for(let x=3;x<w-3;x+=2){const at=clip.in+sourceOffset((x-3)/Math.max(1,w-6)*duration,clip),bin=Math.min(4095,Math.max(0,Math.floor((clip.loop?at%waveform.duration:at)/waveform.duration*4096))),peak=waveform.peaks[bin]/Math.max(.01,waveform.maximum);ctx.moveTo(x,center-peak*amplitude);ctx.lineTo(x,center+peak*amplitude)}ctx.stroke()}
 const zero=dbToY(0,h);const zeroSelected=active&&p.some(point=>point.id===selectedId&&point.valueDb===0);ctx.strokeStyle=zeroSelected?'#e4f0aa99':active?'#dce9a94a':'#dce9a922';ctx.setLineDash(zeroSelected?[]:[3,3]);ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(3,zero);ctx.lineTo(w-3,zero);ctx.stroke();ctx.setLineDash([]);
 ctx.strokeStyle=active?'#e4f0aa':'#afc07888';ctx.lineWidth=active?1.7:1;ctx.beginPath();const startDb=p.length?p[0].valueDb:0;ctx.moveTo(3,dbToY(startDb,h));for(let index=0;index<p.length;index++){const point=p[index],x=xAt(point.time,duration,w),y=dbToY(point.valueDb,h),previous=p[index-1];if(previous?.interpolation==='hold'){ctx.lineTo(x,dbToY(previous.valueDb,h));ctx.lineTo(x,y)}else ctx.lineTo(x,y)}ctx.lineTo(w-3,dbToY(p.length?p.at(-1).valueDb:0,h));ctx.stroke();
 if(active&&!p.length){ctx.font='9px ui-monospace, monospace';ctx.fillStyle='#e4f0aa';ctx.fillText('0 dB',5,Math.min(h-2,zero+11))}
 if(active)for(const point of p){const selected=point.id===selectedId,x=xAt(point.time,duration,w),y=dbToY(point.valueDb,h);ctx.fillStyle=selected?'#f2f8ca':'#172016';ctx.strokeStyle='#dce9a9';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(x,y,selected?5:3.5,0,Math.PI*2);ctx.fill();ctx.stroke();if(selected){const label=`${Math.abs(point.valueDb)<.005?'0.0':point.valueDb.toFixed(1)} dB`,tx=Math.max(4,Math.min(w-58,x+7)),ty=Math.max(11,y-8);ctx.font='10px ui-monospace, monospace';const measure=ctx.measureText(label).width;ctx.fillStyle='#10150eee';ctx.fillRect(tx-3,ty-10,measure+6,14);ctx.fillStyle='#eef6c9';ctx.fillText(label,tx,ty)}}
}

const liveBindings=new Map();let removalObserver;
function watchRemoval(element,dispose){liveBindings.set(element,dispose);if(!removalObserver){removalObserver=new MutationObserver(()=>{for(const [node,cleanup]of liveBindings)if(!node.isConnected){liveBindings.delete(node);cleanup()}});removalObserver.observe(document.body,{childList:true,subtree:true})}}

export function bindClipEnvelope(element,{file,url,getClip,getPoints,setPoints,duration,isActive,selectedId,setSelected,onBegin,onInput,onCommit,onContext}){
 const canvas=element.querySelector('.gain-envelope-canvas');if(!canvas)return()=>{};let hovering=false,drag=null,waveform=null;const controller=new AbortController(),progress=document.createElement('small');progress.className='waveform-progress';progress.style.pointerEvents='none';element.append(progress);
 const render=()=>drawClipEnvelope(canvas,getPoints(),duration(),{active:isActive()||hovering,selectedId:selectedId(),waveform,clip:getClip?.()});
 const local=event=>{const rect=canvas.getBoundingClientRect();return{x:event.clientX-rect.left,y:event.clientY-rect.top,width:rect.width,height:rect.height}};
 const pointAt=event=>{const pos=local(event);if(pos.x<0||pos.x>pos.width||pos.y<0||pos.y>pos.height)return null;const points=normalizeEnvelope(getPoints(),duration());let best=null,distance=Infinity;for(const point of points){const dx=xAt(point.time,duration(),pos.width)-pos.x,dy=dbToY(point.valueDb,pos.height)-pos.y,d=Math.hypot(dx,dy);if(d<distance){distance=d;best=point}}return distance<=9?best:null};
 const lineHit=event=>{const pos=local(event);if(pos.x<3||pos.x>pos.width-3||pos.y<0||pos.y>pos.height)return false;const t=timeAt(pos.x,duration(),pos.width),db=envelopeDbAt(t,getPoints(),0);return Math.abs(dbToY(db,pos.height)-pos.y)<=9};
 element.addEventListener('pointerenter',()=>{hovering=true;render()});element.addEventListener('pointerleave',()=>{if(!drag){hovering=false;render()}});
 element.addEventListener('pointerdown',event=>{if(event.button!==0||event.target.closest('[data-edge]'))return;const point=pointAt(event);if(!point){if(!isActive()||!lineHit(event))return;event.preventDefault();event.stopImmediatePropagation();const pos=local(event),at=timeAt(pos.x,duration(),pos.width),points=addEnvelopePoint(getPoints(),at,envelopeDbAt(at,getPoints(),0)),added=points.reduce((best,value)=>Math.abs(value.time-at)<Math.abs(best.time-at)?value:best);onBegin?.();setPoints(points);setSelected(added.id);onCommit?.();render();return}event.preventDefault();event.stopImmediatePropagation();setSelected(point.id);const start=local(event),startDb=point.valueDb;drag={id:point.id,pointer:event.pointerId,startY:start.y,startDb,grabY:start.y-dbToY(startDb,start.height),latched:startDb===0,began:false};element.setPointerCapture?.(event.pointerId);render();const move=moveEvent=>{if(!drag||moveEvent.pointerId!==drag.pointer)return;if(!drag.began){drag.began=true;onBegin?.()}const pos=local(moveEvent),points=normalizeEnvelope(getPoints(),duration()),index=points.findIndex(value=>value.id===drag.id);if(index<0)return;const snapped=snapEnvelopeDrag(moveEvent.shiftKey?drag.startDb+(drag.startY-pos.y)*.025:yToDb(pos.y-drag.grabY,pos.height),pos.height,drag.latched,moveEvent.shiftKey);drag.latched=snapped.latched;const valueDb=snapped.valueDb;const min=index?points[index-1].time+.001:0,max=index<points.length-1?points[index+1].time-.001:duration();points[index]={...points[index],time:Math.max(min,Math.min(max,timeAt(pos.x,duration(),pos.width))),valueDb};setPoints(points);onInput?.(points[index]);render()};const end=endEvent=>{if(!drag||endEvent.pointerId!==drag.pointer)return;const began=drag.began;drag=null;element.removeEventListener('pointermove',move);element.removeEventListener('pointerup',end);element.removeEventListener('pointercancel',end);if(began)onCommit?.();render()};element.addEventListener('pointermove',move);element.addEventListener('pointerup',end);element.addEventListener('pointercancel',end)},true);
 element.addEventListener('dblclick',event=>{if(event.target.closest('[data-edge]'))return;const point=pointAt(event);if(!point&&!lineHit(event))return;event.preventDefault();event.stopImmediatePropagation();onBegin?.();let points=normalizeEnvelope(getPoints(),duration());if(point){points=points.map(value=>value.id===point.id?{...value,valueDb:0}:value);setSelected(point.id)}else{const pos=local(event),time=timeAt(pos.x,duration(),pos.width),valueDb=envelopeDbAt(time,points,0);points=addEnvelopePoint(points,time,valueDb);setSelected(points.reduce((best,value)=>Math.abs(value.time-time)<Math.abs(best.time-time)?value:best).id)}setPoints(points);onCommit?.();render()},true);
 element.addEventListener('contextmenu',event=>{const point=pointAt(event);if(!point)return;event.preventDefault();event.stopImmediatePropagation();setSelected(point.id);onContext?.(event,point);render()},true);
 waveformFor(file,url,{signal:controller.signal,onProgress:state=>{progress.hidden=state.phase==='ready';progress.textContent=state.phase==='queued'?'WAVEFORM · QUEUED':state.phase==='loading'?`WAVEFORM · ${Math.round(state.progress*100)}%`:'WAVEFORM · UNAVAILABLE'}}).then(value=>{waveform=value;if(element.isConnected)render()});const resize=new ResizeObserver(()=>{if(element.isConnected)render();else resize.disconnect()});resize.observe(canvas);watchRemoval(element,()=>{controller.abort();resize.disconnect()});requestAnimationFrame(render);return render;
}
